def apply(inputs, premises):
    component = inputs['component_id']
    view = inputs['view']
    public = inputs['public_case']
    kernel = inputs['kernel']
    facts = []
    witnesses = []
    reasons = []
    complete = True
    if type(view) is not dict or view.get('extraction_status') != 'complete':
        return part([], [], [], False, [component + '_unread_or_ambiguous'])
    if not support(witnesses, view, public, True):
        complete = False
        add(reasons, component + '_complete_view_requires_current_facts_witness')
    payments = view.get('payments')
    services = view.get('services')
    boundaries = view.get('annual_income_boundaries')
    if type(payments) is not list or type(services) is not list or type(boundaries) is not list:
        return part(facts, [], witnesses, False, reasons + ['payment_or_service_channel_unread'])
    payment_rows = {}
    for record in payments:
        evidence = checked(record, public, True)
        local_id = record.get('local_id')
        payer = record.get('payer')
        payee = record.get('payee')
        payer_text = record.get('payer_text')
        payee_text = record.get('payee_text')
        verb = record.get('transaction_verb')
        precision = record.get('temporal_precision')
        date = record.get('payment_date')
        if evidence is None or type(local_id) is not str or local_id in payment_rows or not all(type(x) is str for x in (payer, payee, payer_text, payee_text, verb)) or precision not in ('full_date', 'year_only', 'unstated'):
            complete = False
            continue
        quote = ' '.join([row['quote'].lower() for row in evidence])
        if payer_text.lower() not in quote or payee_text.lower() not in quote or verb.lower() not in quote:
            complete = False
            add(reasons, 'payment_roles_not_source_explicit')
            continue
        if precision == 'full_date' and not payment_service_events_iso_day(date):
            complete = False
            add(reasons, 'payment_date_not_explicit_full_date')
            continue
        if precision != 'full_date' and date is not None:
            complete = False
            add(reasons, 'year_or_interval_cannot_be_payment_day')
            continue
        payment_rows[local_id] = (record, evidence)
    service_ids = {}
    st = target_service(kernel)
    sc = 0
    for index, record in enumerate(services):
        evidence = checked(record, public, True)
        local_id = record.get('local_id')
        worker = record.get('worker')
        employer = record.get('employer')
        worker_text = record.get('worker_text')
        employer_text = record.get('employer_text')
        basis = record.get('role_basis')
        linked_payment = record.get('linked_payment_local_id')
        if evidence is None or type(local_id) is not str or local_id in service_ids or not all(type(x) is str for x in (worker, employer, worker_text, employer_text)) or basis not in ('explicit_service_roles', 'payment_for_service'):
            complete = False
            continue
        quote = ' '.join([row['quote'].lower() for row in evidence])
        if worker_text.lower() not in quote or employer_text.lower() not in quote:
            complete = False
            add(reasons, 'service_roles_not_source_explicit')
            continue
        if basis == 'payment_for_service':
            if type(linked_payment) is not str or linked_payment not in payment_rows:
                complete = False
                add(reasons, 'service_payment_link_unread')
                continue
            payment_record = payment_rows[linked_payment][0]
            if payment_record.get('payer') != employer or payment_record.get('payee') != worker:
                complete = False
                add(reasons, 'transaction_service_roles_reversed')
                continue
        service = 'general_service_' + str(index)
        if record.get('is_query_service') is True:
            sc += 1
            if type(st) is str:
                service = st
        service_ids[local_id] = service
        put(facts, 'service_', [service])
        put(facts, 'agent_', [service, worker])
        put(facts, 'patient_', [service, employer])
        if type(record.get('service_kind')) is str:
            put(facts, 'purpose_', [service, record.get('service_kind')])
        if type(record.get('service_venue')) is str:
            put(facts, 'location_', [service, record.get('service_venue')])
        if type(record.get('location')) is str:
            put(facts, 'location_', [service, record.get('location')])
            if type(record.get('country')) is str:
                put(facts, 'country_', [record.get('location'), record.get('country')])
        if type(record.get('start_date')) is str:
            put(facts, 'start_', [service, record.get('start_date')])
        if type(record.get('end_date')) is str:
            put(facts, 'end_', [service, record.get('end_date')])
    pt = target_payment(kernel)
    pc = 0
    for index, local_id in enumerate(payment_rows):
        record, evidence = payment_rows[local_id]
        linked_service = record.get('service_local_id')
        if linked_service is not None and linked_service not in service_ids:
            complete = False
            add(reasons, 'payment_links_unknown_service')
            continue
        payment = 'general_payment_' + str(index)
        if record.get('is_query_payment') is True:
            pc += 1
            if type(pt) is str:
                payment = pt
        put(facts, 'payment_', [payment])
        put(facts, 'agent_', [payment, record.get('payer')])
        put(facts, 'patient_', [payment, record.get('payee')])
        if type(record.get('amount')) in (int, float):
            put(facts, 'amount_', [payment, record.get('amount')])
        if type(record.get('medium')) is str:
            put(facts, 'means_', [payment, record.get('medium')])
        if record.get('temporal_precision') == 'full_date':
            put(facts, 'start_', [payment, record.get('payment_date')])
        if type(linked_service) is str:
            put(facts, 'purpose_', [payment, service_ids[linked_service]])
    for record in boundaries:
        if not support(witnesses, record, public, True) or type(record.get('person')) is not str or type(record.get('year')) is not int:
            complete = False
    if type(st) is str and len(services) > 0 and sc != 1:
        complete = False
        add(reasons, 'queried_service_role_not_uniquely_aligned')
    if type(pt) is str and len(payments) > 0 and pc != 1:
        complete = False
        add(reasons, 'queried_payment_role_not_uniquely_aligned')
    if not complete:
        add(reasons, component + '_one_or_more_records_unread_or_invalid')
    return part(facts, [], witnesses, complete, reasons)

def apply(inputs, premises):
    component = inputs['component_id']
    view = inputs['view']
    public = inputs['public_case']
    facts = []
    witnesses = []
    reasons = []
    complete = True
    if type(view) is not dict or view.get('extraction_status') != 'complete':
        return part([], [], [], False, [component + '_unread_or_ambiguous'])
    if not support(witnesses, view, public, True):
        complete = False
        add(reasons, component + '_complete_view_requires_current_facts_witness')
    classifications = view.get('classifications')
    states = view.get('person_states')
    plans = view.get('plans')
    agreements = view.get('agreements')
    terminations = view.get('terminations')
    if type(classifications) is not list or type(states) is not list or type(plans) is not list or type(agreements) is not list or type(terminations) is not list:
        return part(facts, [], witnesses, False, reasons + ['special_native_channels_unread'])
    class_names = {'american_employer': 'american_employer_', 'business': 'business_', 'business_trust': 'business_trust_', 'international_organization': 'international_organization_', 'itemize_deductions': 'itemize_deductions_', 'medical_institution': 'medical_institution_', 'nurses_training_school': 'nurses_training_school_'}
    for index, record in enumerate(classifications):
        evidence = checked(record, public, True)
        kind = record.get('kind')
        subject = record.get('subject')
        subject_text = record.get('subject_text')
        term = record.get('source_term')
        if evidence is None or kind not in class_names or not all(type(x) is str for x in (subject, subject_text, term)):
            complete = False
            continue
        quote = ' '.join([row['quote'].lower() for row in evidence])
        if subject_text.lower() not in quote or term.lower() not in quote:
            complete = False
            continue
        event = 'special_class_' + str(index)
        put(facts, class_names[kind], [event])
        put(facts, 'agent_', [event, subject])
        if kind == 'business' and type(record.get('detail')) is str:
            put(facts, 'type_', [event, record.get('detail')])
        if type(record.get('start_date')) is str:
            put(facts, 'start_', [event, record.get('start_date')])
        if type(record.get('end_date')) is str:
            put(facts, 'end_', [event, record.get('end_date')])
    state_names = {'citizenship': 'citizenship_', 'disability': 'disability_', 'migration': 'migration_', 'nonresident_alien': 'nonresident_alien_', 'retirement': 'retirement_'}
    for index, record in enumerate(states):
        evidence = checked(record, public, True)
        kind = record.get('kind')
        person = record.get('person')
        person_text = record.get('person_text')
        term = record.get('source_term')
        if evidence is None or kind not in state_names or not all(type(x) is str for x in (person, person_text, term)):
            complete = False
            continue
        quote = ' '.join([row['quote'].lower() for row in evidence])
        if person_text.lower() not in quote or term.lower() not in quote:
            complete = False
            continue
        related = record.get('related')
        related_text = record.get('related_text')
        if kind in ('citizenship', 'migration') and (type(related) is not str or type(related_text) is not str or related_text.lower() not in quote):
            complete = False
            continue
        event = 'special_state_' + str(index)
        put(facts, state_names[kind], [event])
        put(facts, 'agent_', [event, person])
        if kind == 'citizenship':
            put(facts, 'patient_', [event, related])
        if kind == 'migration':
            put(facts, 'destination_', [event, related])
            if type(record.get('purpose')) is str:
                put(facts, 'purpose_', [event, record.get('purpose')])
        if type(record.get('start_date')) is str:
            put(facts, 'start_', [event, record.get('start_date')])
        if type(record.get('end_date')) is str:
            put(facts, 'end_', [event, record.get('end_date')])
    for index, record in enumerate(plans):
        if not support(witnesses, record, public, True):
            complete = False
            continue
        beneficiaries = record.get('beneficiaries')
        if type(record.get('employer')) is not str or type(beneficiaries) is not list or not all(type(x) is str for x in beneficiaries):
            complete = False
            continue
        event = 'special_plan_' + str(index)
        put(facts, 'plan_', [event])
        put(facts, 'agent_', [event, record.get('employer')])
        if type(record.get('purpose')) is str:
            put(facts, 'purpose_', [event, record.get('purpose')])
        for beneficiary in beneficiaries:
            put(facts, 'beneficiary_', [event, beneficiary])
    for index, record in enumerate(agreements):
        if not support(witnesses, record, public, True):
            complete = False
            continue
        participants = record.get('participants')
        if type(participants) is not list or len(participants) < 2 or not all(type(x) is str for x in participants):
            complete = False
            continue
        event = 'special_agreement_' + str(index)
        put(facts, 'unemployment_compensation_agreement_', [event])
        for participant in participants:
            put(facts, 'agent_', [event, participant])
    for index, record in enumerate(terminations):
        evidence = checked(record, public, True)
        worker = record.get('worker')
        employer = record.get('employer')
        term = record.get('termination_term')
        if evidence is None or not all(type(x) is str for x in (worker, employer, term)):
            complete = False
            continue
        quote = ' '.join([row['quote'].lower() for row in evidence])
        if term.lower() not in quote:
            complete = False
            continue
        service = 'special_terminated_service_' + str(index)
        event = 'special_termination_' + str(index)
        put(facts, 'service_', [service])
        put(facts, 'agent_', [service, worker])
        put(facts, 'patient_', [service, employer])
        if type(record.get('service_start')) is str:
            put(facts, 'start_', [service, record.get('service_start')])
        if type(record.get('service_end')) is str:
            put(facts, 'end_', [service, record.get('service_end')])
        put(facts, 'termination_', [event])
        put(facts, 'agent_', [event, employer])
        put(facts, 'patient_', [event, service])
        if type(record.get('termination_date')) is str:
            put(facts, 'start_', [event, record.get('termination_date')])
        condition_kind = record.get('condition_kind')
        condition_term = record.get('condition_term')
        if condition_kind in ('disability', 'death'):
            if type(condition_term) is not str or condition_term.lower() not in quote:
                complete = False
                continue
            condition = 'special_termination_condition_' + str(index)
            put(facts, condition_kind + '_', [condition])
            put(facts, 'agent_', [condition, worker])
            put(facts, 'reason_', [event, condition])
            if type(record.get('condition_date')) is str:
                put(facts, 'start_', [condition, record.get('condition_date')])
    if not complete:
        add(reasons, component + '_one_or_more_records_unread_or_invalid')
    return part(facts, [], witnesses, complete, reasons)
